import React, { useState } from 'react';
import { User, MapPin, Search, X, FileText, AlertOctagon, Calendar, CreditCard, ChevronRight, Fingerprint, Clock, ShieldCheck, Phone } from 'lucide-react';

const CitizensTab = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState(null);
  const [activeFilter, setActiveFilter] = useState('PROFILE');

  const citizens = [
    { id: 'CZ-8821', name: 'ARJUN MEHTA', area: 'GANDHI_NAGAR', zone: 'ZONE_A', status: 'ACTIVE', phone: '+91 98XXX XXXXX', joined: '12_JAN_2025' },
    { id: 'CZ-4412', name: 'SARA KHAN', area: 'SILICON_VALLEY', zone: 'ZONE_C', status: 'OVERDUE', phone: '+91 88XXX XXXXX', joined: '05_FEB_2024' },
    { id: 'CZ-9003', name: 'VIKRAM SINGH', area: 'OLD_TOWN', zone: 'ZONE_B', status: 'ACTIVE', phone: '+91 77XXX XXXXX', joined: '22_NOV_2024' },
  ];

  return (
    <div className="w-full h-full flex flex-col gap-6 font-black italic uppercase tracking-tighter select-none">

      {/* 🔍 SEARCH RIG (Lemon Yellow) */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-[#FFF24D] p-5 rounded-[24px] border-[4px] border-[#47510B] shadow-[6px_6px_0_0_#47510B]">
        <div className="flex items-center gap-3 text-[#47510B]">
          <Fingerprint size={32} />
          <h1 className="text-2xl leading-none">CITIZEN_REGISTRY</h1>
        </div>
        <div className="relative w-full md:w-80">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-[#47510B]/40" size={18} />
          <input 
            type="text" 
            placeholder="SEARCH_RECORDS..." 
            className="w-full bg-white border-[3px] border-[#47510B] rounded-xl p-2.5 pl-12 outline-none text-xs shadow-[3px_3px_0_0_#47510B]"
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      {/* 📋 LIST: Added pb-40 to prevent the bottom cut-off */}
      <div className="flex-grow overflow-y-auto pr-2 pb-40 custom-scrollbar grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {citizens.map(c => (
          <div 
            key={c.id} 
            onClick={() => setSelectedCitizen(c)} 
            className="bg-white border-[4px] border-[#47510B] p-5 rounded-[32px] shadow-[4px_4px_0_0_#47510B] hover:translate-x-1 hover:bg-[#FDFAD8] transition-all cursor-pointer flex justify-between items-center group"
          >
            <div className="min-w-0">
              <p className="text-[10px] text-[#CAD23C] mb-1">{c.id}</p>
              <h3 className="text-xl truncate text-[#47510B]">{c.name}</h3>
              <p className="text-[10px] opacity-40">{c.area}</p>
            </div>
            <ChevronRight size={24} className="text-[#47510B] group-hover:translate-x-1 transition-transform" />
          </div>
        ))}
      </div>

      {/* 🏗️ SLIM DOSSIER MODAL (Strict Color Palette) */}
      {selectedCitizen && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6">
          <div className="absolute inset-0 bg-[#47510B]/80 backdrop-blur-sm animate-in fade-in duration-200" onClick={() => setSelectedCitizen(null)} />

          <div className="relative w-full max-w-4xl h-[80vh] bg-[#FDFAD8] border-[6px] border-[#47510B] rounded-[50px] shadow-[15px_15px_0_0_#000] overflow-hidden flex flex-col animate-in zoom-in-95 duration-200">

            {/* COMPACT HEADER (Grassy Green) */}
            <div className="bg-[#47510B] p-6 text-white flex justify-between items-center shrink-0">
                <div className="flex gap-4 items-center">
                    <div className="w-14 h-14 bg-[#FFF24D] border-2 border-white rounded-2xl flex items-center justify-center text-[#47510B]">
                        <User size={32} strokeWidth={3} />
                    </div>
                    <div>
                        <p className="text-[10px] text-[#CAD23C] tracking-widest">RECORD_REF: {selectedCitizen.id}</p>
                        <h2 className="text-3xl md:text-4xl leading-none">{selectedCitizen.name}</h2>
                    </div>
                </div>
                <button onClick={() => setSelectedCitizen(null)} className="hover:bg-[#AB1717] p-3 rounded-2xl transition-all"><X size={28} /></button>
            </div>

            {/* TAB NAV (Blue Linen) */}
            <div className="bg-[#A1AED1] p-2 flex gap-2 overflow-x-auto no-scrollbar shrink-0 border-b-[4px] border-[#47510B]">
              {['PROFILE', 'REPORTS', 'PENALTIES', 'SCHEDULES', 'SUBS'].map(id => (
                <button 
                  key={id}
                  onClick={() => setActiveFilter(id)}
                  className={`px-6 py-2.5 rounded-xl text-[10px] font-black border-2 transition-all ${activeFilter === id ? 'bg-[#FFF24D] text-[#47510B] border-[#47510B] shadow-[2px_2px_0_0_#47510B]' : 'bg-transparent text-[#47510B]/60 border-transparent hover:text-[#47510B]'}`}
                >
                  {id}
                </button>
              ))}
            </div>

            {/* CONTENT AREA: pb-20 for safe scroll inside modal */}
            <div className="flex-grow p-8 overflow-y-auto pb-20 custom-scrollbar">

              {activeFilter === 'PROFILE' && (
                <div className="grid md:grid-cols-2 gap-8 animate-in slide-in-from-right-4">
                  <div className="space-y-6">
                    <div>
                      <label className="text-[#AB1717] text-[10px] mb-1 block">REGISTRATION_ADDRESS</label>
                      <p className="text-2xl leading-tight text-[#47510B]">{selectedCitizen.area}, HYDERABAD, IN</p>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="bg-white p-4 rounded-2xl border-[3px] border-[#47510B] shadow-[4px_4px_0_0_#A1AED1]">
                            <label className="text-[8px] opacity-40">COMM_LINE</label>
                            <p className="text-sm font-black text-[#47510B]">{selectedCitizen.phone}</p>
                        </div>
                        <div className="bg-white p-4 rounded-2xl border-[3px] border-[#47510B] shadow-[4px_4px_0_0_#CAD23C]">
                            <label className="text-[8px] opacity-40">NETWORK_SINCE</label>
                            <p className="text-sm font-black text-[#47510B]">{selectedCitizen.joined}</p>
                        </div>
                    </div>
                  </div>
                  <div className="bg-[#FFF24D] border-[4px] border-[#47510B] rounded-[32px] p-8 flex flex-col items-center justify-center text-center shadow-[8px_8px_0_0_#47510B]">
                     <ShieldCheck size={56} className="text-[#47510B] mb-3" />
                     <h3 className="text-2xl text-[#47510B]">VERIFIED_STATUS</h3>
                     <p className="text-[10px] mt-2 opacity-60">GEOTAG_LOCKED // {selectedCitizen.zone}</p>
                  </div>
                </div>
              )}

              {activeFilter === 'REPORTS' && (
                <div className="space-y-3 animate-in slide-in-from-right-4">
                  {[1, 2].map(i => (
                    <div key={i} className="bg-white border-[3px] border-[#47510B] p-5 rounded-2xl flex justify-between items-center shadow-[4px_4px_0_0_#CAD23C]">
                        <div>
                            <h4 className="text-xl text-[#47510B]">INCIDENT_REP_00{i}</h4>
                            <p className="text-[10px] opacity-40 tracking-widest">22_MAR_2026</p>
                        </div>
                        <span className="text-[10px] bg-[#CAD23C] text-[#47510B] px-4 py-1.5 rounded-lg border-2 border-[#47510B]">RESOLVED</span>
                    </div>
                  ))}
                </div>
              )}

              {activeFilter === 'PENALTIES' && (
                <div className="space-y-3 animate-in slide-in-from-right-4">
                  {[1].map(i => (
                    <div key={i} className="bg-white border-[3px] border-[#AB1717] p-5 rounded-2xl flex justify-between items-center shadow-[4px_4px_0_0_#AB1717]">
                        <h4 className="text-xl text-[#AB1717]">NON_SEGREGATED_WASTE</h4>
                        <p className="text-3xl text-[#AB1717]">₹500</p>
                    </div>
                  ))}
                </div>
              )}

              {activeFilter === 'SCHEDULES' && (
                <div className="grid grid-cols-2 gap-4 animate-in slide-in-from-right-4">
                  {['MONDAY_08:00', 'WEDNESDAY_09:00'].map(s => (
                    <div key={s} className="bg-[#47510B] p-6 rounded-3xl text-white text-center border-4 border-[#FFF24D]">
                       <Calendar size={24} className="mx-auto mb-2 opacity-30" />
                       <p className="text-xs">{s.split('_')[0]}</p>
                       <p className="text-2xl">{s.split('_')[1]}</p>
                    </div>
                  ))}
                </div>
              )}

              {activeFilter === 'SUBS' && (
                <div className="bg-[#FFF24D] border-[4px] border-[#47510B] p-8 rounded-[40px] flex flex-col items-center justify-center text-center shadow-[8px_8px_0_0_#A1AED1] animate-in slide-in-from-right-4">
                   <CreditCard size={48} className="mb-4 text-[#47510B]" />
                   <h3 className="text-4xl text-[#47510B]">PREMIUM_ULTRA</h3>
                   <p className="text-sm opacity-60 mt-2">RECURRING_BILLING: ₹1,200/mo</p>
                   <button className="mt-6 bg-[#47510B] text-white px-8 py-3 rounded-2xl text-[10px] hover:bg-[#AB1717] transition-colors">UPDATE_PLAN</button>
                </div>
              )}

            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CitizensTab;
